import fs from 'fs';
import path from 'path';
import { pathToFileURL } from 'url';
import vm from 'vm';
import { Command } from 'commander';
import { getPluginDir, readConfig } from '../utils/config.js';

type SandboxOptions = {
  timeout?: number;
  globals?: Record<string, unknown>;
};

function runSandboxed(code: string, filename: string, opts: SandboxOptions = {}) {
  const sandbox: Record<string, unknown> = {
    module: {},
    exports: {},
    console,
    setTimeout,
    clearTimeout,
    ...opts.globals
  };
  vm.createContext(sandbox);
  vm.runInContext(code, sandbox, { filename, timeout: opts.timeout ?? 3000 });
  const fn = (sandbox.module as any).exports?.default || (sandbox.exports as any)?.default;
  return fn;
}

export async function loadPlugins(program: Command) {
  const dir = getPluginDir();
  if (!fs.existsSync(dir)) return;
  const cfg = readConfig();
  const files = fs.readdirSync(dir).filter(f => f.endsWith('.js') || f.endsWith('.mjs'));
  for (const file of files) {
    try {
      const allow = cfg.pluginPolicies?.allow;
      const deny = cfg.pluginPolicies?.deny;
      if (deny && deny.includes(file)) {
        console.warn(`Skipping plugin ${file} (deny list)`);
        continue;
      }
      if (allow && !allow.includes(file)) {
        console.warn(`Skipping plugin ${file} (not in allow list)`);
        continue;
      }
      const fullPath = path.join(dir, file);
      const code = fs.readFileSync(fullPath, 'utf8');
      const fn = runSandboxed(code, fullPath, { timeout: 3000, globals: { Command } });
      if (typeof fn === 'function') fn(program);
    } catch (err) {
      console.error('Failed to load plugin', file, err);
    }
  }
}
